65: void PlatformThread::createRWMutex(decaf_rwmutex_t* mutex) {
66:     *mutex = new RWLOCK;
67: 
68:     (*mutex)->readers = 0;
69: 
70:     if (!((*mutex)->readEvent = ::CreateEvent(NULL, TRUE, FALSE, NULL))) {
71:         *mutex = NULL;
