85: void PlatformThread::readerLockMutex(decaf_rwmutex_t mutex) {
86: 
87:     DWORD code = ::WaitForSingleObject(mutex->writeMutex, INFINITE);
88: 
89:     if (code == WAIT_FAILED || code == WAIT_TIMEOUT) {
90:         throw RuntimeException(
91:             __FILE__, __LINE__, "Failed to wait for lock on RW object.");
92:     }
93: 
94:     // The write mutex lock prevents writers from entering while we add a
95:     // reader, and protects the read counter from races.
96:     ::InterlockedIncrement(&mutex->readers);
97: 
98:     if (! ::ResetEvent(mutex->readEvent)) {
99:         throw RuntimeException(
100:             __FILE__, __LINE__, "Failed to reset RW Event object.");
101:     }
102: 
103:     if (! ReleaseMutex(mutex->writeMutex)) {
104:         throw RuntimeException(
105:             __FILE__, __LINE__, "Failed to release RW Mutex object.");
106:     }
