110: void PlatformThread::writerLockMutex(decaf_rwmutex_t mutex) {
111: 
112:     DWORD code = ::WaitForSingleObject(mutex->writeMutex, INFINITE);
113: 
114:     if (code == WAIT_FAILED || code == WAIT_TIMEOUT) {
115:         throw RuntimeException(
116:             __FILE__, __LINE__, "Failed to wait for lock on RW object.");
117:     }
118: 
119:     // Once we own the lock we must wait for the readers to all leave.
120:     if (mutex->readers) {
121: 
122:         code = ::WaitForSingleObject(mutex->readEvent, INFINITE);
123:         if (code == WAIT_FAILED || code == WAIT_TIMEOUT) {
124: 
125:             ::ReleaseMutex(mutex->writeMutex);
