135: 
136:     DWORD code = ::WaitForSingleObject(mutex->writeMutex, 0);
137: 
138:     if (code == WAIT_FAILED) {
139:         throw RuntimeException(
140:             __FILE__, __LINE__, "Failed to wait for lock on RW object.");
141:     }
142: 
143:     if (code == WAIT_TIMEOUT) {
144:         return false;
145:     }
146: 
147:     // The write mutex lock prevents writers from entering while we add a
148:     // reader, and protects the read counter from races.
149:     ::InterlockedIncrement(&mutex->readers);
