191: ////////////////////////////////////////////////////////////////////////////////
192: void PlatformThread::unlockRWMutex(decaf_rwmutex_t mutex) {
193: 
194:     DWORD result = 0;
195: 
196:     if (! ::ReleaseMutex(mutex->writeMutex)) {
197:         result = ::GetLastError();
198:     }
199: 
200:     // If not the owner then we must be a reader holding the lock.
201:     if (result == ERROR_NOT_OWNER) {
202: 
203:         // If there are readers and this is the last release, signal the event
204:         // so that any waiting writers get nofitied.
205:         if (mutex->readers > 0 && ::InterlockedDecrement(&mutex->readers) == 0) {
206: 
207:            if (! ::SetEvent(mutex->readEvent)) {
208:                throw RuntimeException(
209:                    __FILE__, __LINE__, "Failed to signal OS event object.");
210:            }
211:         }
212:     } else if (result != 0) {
213:         throw RuntimeException(
214:             __FILE__, __LINE__, "Failed to signal unlock OS Mutex object.");
215:     }
216: }
