291: ////////////////////////////////////////////////////////////////////////////////
292: bool PlatformThread::interruptibleWaitOnCondition(decaf_condition_t condition, decaf_mutex_t mutex,
293:                                                   long long mills, int nanos, CompletionCondition& complete) {
294: 
295:     DWORD startTime = ::GetTickCount();
296:     DWORD timeOut = (DWORD)mills;
297:     DWORD initialTimeOut = (DWORD)mills;
298: 
299:     bool result = false;
300: 
301:     do {
302: 
303:         ::ResetEvent(condition);
304:         PlatformThread::unlockMutex(mutex);
305:         int timedOut = ::WaitForSingleObject(condition, timeOut);
306:         PlatformThread::lockMutex(mutex);
307: 
308:         if (timedOut == WAIT_TIMEOUT) {
309: 
310:             // interruption events take precedence over timeout.
311:             if (complete(true)) {
312:                break;
313:             }
314: 
315:             result = true;
316:             break;
317:         }
318: 
319:         // check if spurious wake or intentional.
320:         if (complete(false)) {
321:             break;
322:         }
323: 
324:         timeOut = initialTimeOut - (::GetTickCount() - startTime);
325:         if( timeOut < 0) {
326:             timeOut = 0;
327:         }
328: 
329:     } while(true);
330: 
331:     return result;
332: }
