308:             throw IOException(__FILE__, __LINE__, "The socket was not yet created.");
309:         }
310: 
311:         // Create the Address data
312:         checkResult(apr_sockaddr_info_get(&impl->remoteAddress, hostname.c_str(), APR_INET, (apr_port_t) port, 0, impl->apr_pool.getAprPool()));
313: 
314:         int oldNonblockSetting = 0;
315:         apr_interval_time_t oldTimeoutSetting = 0;
316: 
317:         // Record the old settings.
318:         apr_socket_opt_get(impl->socketHandle, APR_SO_NONBLOCK, &oldNonblockSetting);
319:         apr_socket_timeout_get(impl->socketHandle, &oldTimeoutSetting);
320: 
321:         // Temporarily make it what we want, blocking.
322:         apr_socket_opt_set(impl->socketHandle, APR_SO_NONBLOCK, 0);
