332:         checkResult (apr_socket_connect(impl->socketHandle, impl->remoteAddress) );
333: 
334:         // Now that we are connected, we want to go back to old settings.
335:         apr_socket_opt_set(impl->socketHandle, APR_SO_NONBLOCK, oldNonblockSetting);
336:         apr_socket_timeout_set(impl->socketHandle, oldTimeoutSetting);
337: 
338:         // Now that we connected, cache the port value for later lookups.
339:         this->port = port;
340:         this->impl->connected = true;
