636: int TcpSocket::read(unsigned char* buffer, int size, int offset, int length) {
637: 
638:     try {
639:         if (isClosed()) {
640:             throw IOException(__FILE__, __LINE__, "The Stream has been closed");
641:         }
642: 
643:         if (this->impl->inputShutdown == true) {
644:             return -1;
645:         }
646: 
647:         if (length == 0) {
648:             return 0;
649:         }
650: 
651:         if (buffer == NULL) {
652:             throw NullPointerException(__FILE__, __LINE__, "Buffer passed is Null");
653:         }
654: 
655:         if (size < 0) {
656:             throw IndexOutOfBoundsException(__FILE__, __LINE__,
657:                 "size parameter out of Bounds: %d.", size);
658:         }
659: 
660:         if (offset > size || offset < 0) {
661:             throw IndexOutOfBoundsException(__FILE__, __LINE__,
662:                 "offset parameter out of Bounds: %d.", offset);
663:         }
664: 
665:         if (length < 0 || length > size - offset) {
666:             throw IndexOutOfBoundsException(__FILE__, __LINE__,
667:                 "length parameter out of Bounds: %d.", length);
668:         }
669: 
670:         apr_size_t aprSize = (apr_size_t) length;
671:         apr_status_t result = APR_SUCCESS;
672: 
673:         // Read data from the socket, size on input is size of buffer, when done
674:         // size is the number of bytes actually read, can be <= bufferSize.
675:         result = apr_socket_recv(impl->socketHandle, (char*) buffer + offset, &aprSize);
676: 
677:         // Check for EOF, on windows we only get size==0 so check that to, if we
678:         // were closed though then we throw an IOException so the caller knows we
679:         // aren't usable anymore.
680:         if ((APR_STATUS_IS_EOF( result ) || aprSize == 0) && !isClosed()) {
681:             this->impl->inputShutdown = true;
682:             return -1;
683:         }
684: 
685:         if (isClosed()) {
686:             throw IOException(__FILE__, __LINE__, "The connection is closed");
687:         }
688: 
689:         if (result != APR_SUCCESS) {
690:             throw IOException(__FILE__, __LINE__,
691:                 "Socket Read Error - %s", SocketError::getErrorString().c_str());
692:         }
693: 
694:         return (int) aprSize;
695:     }
696:     DECAF_CATCH_RETHROW(IOException)
697:     DECAF_CATCH_RETHROW(NullPointerException)
698:     DECAF_CATCH_RETHROW(IndexOutOfBoundsException)
699:     DECAF_CATCHALL_THROW(IOException)
700: }
