703: void TcpSocket::write(const unsigned char* buffer, int size, int offset, int length) {
704: 
705:     try {
706: 
707:         if (length == 0) {
708:             return;
709:         }
710: 
711:         if (buffer == NULL) {
712:             throw NullPointerException(__FILE__, __LINE__,
713:                 "TcpSocket::write - passed buffer is null");
714:         }
715: 
716:         if (isClosed()) {
717:             throw IOException(__FILE__, __LINE__,
718:                 "TcpSocket::write - This Stream has been closed.");
719:         }
720: 
721:         if (size < 0) {
722:             throw IndexOutOfBoundsException(__FILE__, __LINE__,
723:                 "size parameter out of Bounds: %d.", size);
724:         }
725: 
726:         if (offset > size || offset < 0) {
727:             throw IndexOutOfBoundsException(__FILE__, __LINE__,
728:                 "offset parameter out of Bounds: %d.", offset);
729:         }
730: 
731:         if (length < 0 || length > size - offset) {
732:             throw IndexOutOfBoundsException(__FILE__, __LINE__,
733:                 "length parameter out of Bounds: %d.", length);
734:         }
735: 
736:         apr_size_t remaining = (apr_size_t) length;
737:         apr_status_t result = APR_SUCCESS;
738: 
739:         const unsigned char* lbuffer = buffer + offset;
740: 
741:         while (remaining > 0 && !isClosed()) {
742: 
743:             // On input remaining is the bytes to send, after return remaining
744:             // is the amount actually sent.
745:             result = apr_socket_send(this->impl->socketHandle, (const char*) lbuffer, &remaining);
746: 
747:             if (result != APR_SUCCESS || isClosed()) {
748:                 throw IOException(__FILE__, __LINE__,
749:                     "TcpSocketOutputStream::write - %s", SocketError::getErrorString().c_str());
750:             }
751: 
752:             // move us to next position to write, or maybe end.
753:             lbuffer += remaining;
754:             remaining = length - remaining;
755:         }
756:     }
757:     DECAF_CATCH_RETHROW(IOException)
758:     DECAF_CATCH_RETHROW(NullPointerException)
759:     DECAF_CATCH_RETHROW(IndexOutOfBoundsException)
760:     DECAF_CATCHALL_THROW(IOException)
761: }
